Action.ExecScriptExpression:
using System;
using System.Windows.Forms;
using Triggernometry.Core;

bool showError = "${isInit}" == "0";
var postNamazu = RealPlugin.InstanceHook(null, "PostNamazu.PostNamazu");
if (postNamazu.pluginObj == null)
{
    if (showError) MessageBox.Show("鲶鱼精邮差插件未安装或未启动。", "PostNamazu 鲶鱼精邮差", MessageBoxButtons.OK, MessageBoxIcon.Error);
    return;
}

var localVersion = new Version(postNamazu.FileVersion);
var remoteVersion = new Version("${env:namazu}");

if (localVersion < remoteVersion)
{
    if (showError) MessageBox.Show($"鲶鱼精邮差插件版本 {localVersion} 低于所需最低版本 {remoteVersion}。\n正在尝试更新。", "PostNamazu 鲶鱼精邮差", MessageBoxButtons.OK, MessageBoxIcon.Warning);
    RealPlugin.Instance.UpdatePostNamazu("${env:namazu}");
    return;
}
if (showError) MessageBox.Show($"鲶鱼精邮差插件版本 {localVersion} 不低于所需最低版本 {remoteVersion}。\n可以继续测试功能。", "PostNamazu 鲶鱼精邮差", MessageBoxButtons.OK, MessageBoxIcon.Information);

