Action.ExecScriptExpression:
using Advanced_Combat_Tracker;
using System.Collections.Generic;
using System.Windows.Forms;
using System.Linq;
// 反射 API 限制，只能获取 Type 的名称，手动转换一下
var typeToName = new Dictionary<string, string>
{
    { "FFXIV_ACT_Plugin.FFXIV_ACT_Plugin", "FFXIV_ACT_Plugin" },
    { "RainbowMage.OverlayPlugin.PluginLoader", "OverlayPlugin" },
    { "PostNamazu.PostNamazu", "PostNamazu" },
    { "TriggernometryProxy.ProxyPlugin", "Triggernometry" },
    { "ACT.FoxTTS.FoxTTSPlugin", "FoxTTS" },
    { "Cafe.Matcha.MatchaInit", "Matcha" },
    { "ACT.FFXIVPing.FFXIVPingPlugin", "FFXIVPing" },
    { "Cactbot.PluginLoader", "Cactbot" },
    { "StarlightBreaker.MainClass", "StarlightBreaker" },
    { "AccurateWorldTravelQueue.PluginMain", "AccurateWorldTravelQueue" },
    { "ACT.TTS_CN.PluginMain", "TTS_CN" },
    { "SilverDasher.Loader.Loader", "SilverDasher" }
};

var pluginNames = ActGlobals.oFormActMain.ActPlugins
    .Where(p => p.cbEnabled.Checked)
    .Select(p => p.pluginObj.GetType().ToString())
    .Select(typeName => typeToName.TryGetValue(typeName, out var name) ? name : typeName)
    .Where(name => !name.ToLower().Contains("cafestore"))
    .ToList();

List<string> errors = new List<string>();

if (pluginNames[0] != "FFXIV_ACT_Plugin" ||
    pluginNames[1] != "OverlayPlugin" ||
    pluginNames[2] != "Triggernometry")
{
    errors.Add("· 前三个插件按顺序应为：\n  1. FFXIV_ACT_Plugin\n  2. OverlayPlugin\n  3. Triggernometry");
}
var namazuIdx = pluginNames.IndexOf("PostNamazu");
var cactbotIdx = pluginNames.IndexOf("Cactbot");
var trigIdx = pluginNames.IndexOf("Triggernometry");
var overlayIdx = pluginNames.IndexOf("OverlayPlugin");
if (namazuIdx >= 0 && namazuIdx < trigIdx)
{
    errors.Add("· 鲶鱼精邮差 PostNamazu 应置于触发器 Triggernometry 后面。");
}
if (cactbotIdx >= 0 && cactbotIdx < overlayIdx)
{
    errors.Add("· Cactbot 应置于 OverlayPlugin 后面。");
}
if (errors.Any())
{
    var detail = "${isManual}" == "1" ? "" : "\n（ACT 主界面 - 插件 - Triggernometry - 页面下方 远程触发器）";
    MessageBox.Show(
        "ACT 插件顺序错误，插件不会正常工作：\n\n" + string.Join("\n", errors) + "\n\n你需要按远程触发器 - 自检工具箱中的说明调整。" + detail + "\n建议截图此弹窗以便调整。\n修复后需要重启 ACT。\n\n当前插件列表：\n· " + string.Join("\n· ", pluginNames),
        "Triggernometry 触发器自检：插件顺序", MessageBoxButtons.OK, MessageBoxIcon.Error);
}
else if ("${isManual}" == "1")
{
    MessageBox.Show(
        "ACT 插件顺序正确。\n\n当前插件列表：\n· " + string.Join("\n· ", pluginNames),
        "触发器自检：插件顺序", MessageBoxButtons.OK, MessageBoxIcon.Information);
}

