using Triggernometry.UI.CustomControls;
using Triggernometry.UI.Forms;
using Triggernometry.Core.Scripting;

Validater.Show();

public static class Validater
{
    const string group1 = "556836295";
    const string group2 = "133514183";
    const string group3 = "612703030";

    public static void Show()
    {
        var form = new SimpleInputForm("输入你要加的群号：", ExpressionTextBox.SupportedExpressionTypeEnum.Numeric, group3);
        form.TopMost = true;
        form.Shown += (_, __) => form.BringToFront();
        string result = form.GetInput()?.Trim();
        if (string.IsNullOrEmpty(result)) return;
        switch (result)
        {
            case group1: MessageBox.Show("本群并非答疑群，使用遇到问题请加群 612703030。\n本群验证问题答案为：\n\n写出用于获取触发器表格变量 a 第 2 行 1 列的值的表达式，不含外侧括号 $" + "{ }，无空格。\n如果你的回答包含 \"var\"，请使用简称，删除这三个字母即可。\n\n如果你不知道，可以查阅 Triggernometry GitHub Wiki 获取相关介绍。", "", MessageBoxButtons.OK, MessageBoxIcon.Information); return;
            case group2: MessageBox.Show($"此群已暂停开放。", "", MessageBoxButtons.OK, MessageBoxIcon.Information); return;
            case group3: MessageBox.Show("本群可直接进入，仅用于临时提问。验证问题见群简介，如果看不见的话可以切换设备看。", "", MessageBoxButtons.OK, MessageBoxIcon.Warning); return;
            default: MessageBox.Show("群号错误。", "", MessageBoxButtons.OK, MessageBoxIcon.Warning); return;
        }
    }
}

