Action.ExecScriptExpression:
using System;
using Triggernometry;
using Triggernometry.PluginBridges.BridgeNamazu;
using Triggernometry.PluginBridges.BridgeNamazu.Modules;

BridgeNamazu.InitializeModules(() => {
    // 示例：Sideload（版本更新后可覆写偏移或扫描方法等）
    // var module = BridgeNamazu.GetModule<EntityModule>();
    // module.PosOffset = () => BridgeNamazu.NamazuPlugin.IsCN ? 0x74 : 0x70;
    // module.ScanMethod = () => { module.GetStatusIndexPtr = ModuleBase.Scanner.ScanText("xxx"); };
    var mEnt = BridgeNamazu.GetModule<EntityModule>();
    mEnt.IdOffset = () => 0x78;
    mEnt.PosOffset = () => 0xB0;
    mEnt.ScaleOffset = () => 0xC4;
    mEnt.ModelRelPosOffset = () => 0xE0;
    mEnt.ModelOffset = () => 0x100;
    mEnt.StatusLoopVfxOffset = () => 0x1C8;
    mEnt.OpacityOffset = () => 0x22D8;
    mEnt.ModelStatusOffset = () => 0x118;
    var mCam = BridgeNamazu.GetModule<CameraModule>();
    mCam.OffsetsCN = mCam.OffsetsGlobal;
});

Action.NamedCallbackParam:
Omen: ${d:tmp_data[omen]}
delay: 0.001 + 0${d:tmp_data[delay]}
t: ${if: ${d:tmp_data.ekey(t)} ? ${d:tmp_data[t]} : [简易播报] 绘图未提供 t 参数 }
Tag: ${if: ${d:tmp_data.ekey(tag)} ? ${d:tmp_data[tag]} : 简易播报_${sid}_${aid} }
Pos: ${x}, ${y}, ${z}
Angle: ${h}
Scale: ${if: ${d:tmp_data.ekey(scale)} ? ${d:tmp_data[scale]} : [简易播报] 绘图未提供 scale 参数 }
Color: ${if: ${d:tmp_data.ekey(color)} ? ${d:tmp_data[color]} : 1, 1, 1, 1 }

Omen: ${d:tmp_data[omen]}
delay: 0.001 + 0${d:tmp_data[delay]}
t: ${if: ${d:tmp_data.ekey(t)} ? ${d:tmp_data[t]} : [简易播报] 绘图未提供 t 参数 }
Tag: ${if: ${d:tmp_data.ekey(tag)} ? ${d:tmp_data[tag]} : 简易播报_${sid}_${aid} }
Pos: ${x}, ${y}, ${z}
Angle: ${h} + π/2
Scale: ${if: ${d:tmp_data.ekey(scale)} ? ${d:tmp_data[scale]} : [简易播报] 绘图未提供 scale 参数 }
Color: ${if: ${d:tmp_data.ekey(color)} ? ${d:tmp_data[color]} : 1, 1, 1, 1 }

// 左侧箭头可以展开为多行模式
// 双斜线开始的行会当做为注释行，和空行一起被忽略
// 所有参数的顺序不重要，每行提供一个参数

// 采用日志中的坐标系，即正东 x+，正南 y+，正上 z+
// 角度从正北开始逆时针递增，如 北 西 南 东 分别为： ±π, -π/2, 0, π/2

// 必须参数：action，代表标点模式
// place 模式下允许你输入一组相对坐标
action: place

// 可选参数：scaleX scaleY scaleZ：坐标在各个方向上的缩放尺度，负数即为反向
// 未提供时的默认值：均为 1
scaleX: 2
scaleY: -2
// 如果尺度相同，可以使用 scale: 2 简化

// 可选参数 θ：旋转角度，可以理解为将这个相对坐标系的正北旋转至哪个绝对方向
// 未提供时的默认值：-π （将正北旋转至正北，即未旋转）
θ: π/2
// 也可以写作角度，如 θ: 90°

// 可选参数 center：中心坐标
// 下方演示的是使用触发器的实体查询功能获取并填入自身坐标
// 未提供时的默认值：0, 0, 0
center: ${_me.x}, ${_me.y}, ${_me.z}

// 提供的坐标首先经过缩放变换，其次经过平面旋转，最后平移至中心坐标

// 下方给出所有相对坐标：
A: 0, -4, 0
// z = 0 可以省略：
B: 4, -4
// 也可以使用极坐标模式：polar [r], [θ]：
C: polar 4, 90°
// 也可以结合两种模式，以平面直角坐标系下的坐标为中心进一步添加一个极坐标系的偏移：
D: 0, 4 polar 2, 30°
// 清除一个标点：
1: clear
// “清除”一个标点，实为移动到看不见的位置，使之下次出现时没有淡入动画：
2: fakeclear
// 没有提供的标点会被忽略，保持标点的原状态
// 3:... 4:...

// 三条 hyphen 连字符为分隔线，代表另起一条指令，所有指令依次执行
---

// circle 模式下通过给定的圆心和半径将所有点标记在圆周的等分位置
action: circle

// 必须参数：waymarks，从正北开始所有的标点
// 可以使用 _ 表示这个位置依旧需要等分，但是并不放置一个标点，如下面代表八等分圆但正南不标点
waymarks: ABCD_234

// 必须参数：r，半径
r: 5

// 必须参数：center 圆心坐标
center: ${_me.x}, ${_me.y}, ${_me.z}

// 可选参数：θ，与 place 中类似
θ: -π

// linear（连接两个点）和 arc（朝某个方向标记圆弧）指令还没写介绍，有兴趣可以看代码

Action.ExecScriptExpression:
using System;
using System.Collections.Generic;
using System.Linq;
using Triggernometry.Core;
using Triggernometry.Core.Variables;
using Triggernometry.Expressions.String.Utils;
using static Triggernometry.Core.Scripting.ScriptHelper;
using static Triggernometry.PluginBridges.BridgeFFXIV;


RealPlugin.Instance.RegisterNamedCallback(
    "HoneyBeeRanking",
    new Action<object, string>(HoneyBeeRanking.Callback),
    null,
    registrant: "蜂蜂小甜心 大航海排行 by 阿洛"
);

public class HoneyBeeRanking
{
    string channel; // 发消息的频道
    bool isSimp; // 使用简体中文（国服）
    Dictionary<string, VariableDictionary> currentPlayers;

    List<Player> Ranking;
    List<string> RecentHexIds;

    public HoneyBeeRanking()
    {
        isSimp = !GetMyself().GetValue("name").ToString().Contains(" ");
        channel = GetDictVariable(true, "HoneyBeeRanking")?.GetValue("channel")?.ToString() ?? "";
        if (string.IsNullOrWhiteSpace(channel))
            channel = "p";
        currentPlayers = GetAllEntities()
            .Where(vd => vd.GetValue("id").ToString().StartsWith("10"))
            .ToDictionary(vd => vd.GetValue("id").ToString(), vd => vd);
    }

    public static void Callback(object _, string arg)
    {
        var instance = new HoneyBeeRanking();
        switch (arg.ToLower().Trim())
        {
            case "check":       // 当前队伍中有超过三个已记录的人则开启（输出变量 tmp_on）
                var recordedIds = new HashSet<string>(instance.ParseRecordedPlayersFromTable().Select(p => p.HexId));
                var count = instance.currentPlayers.Keys.Count(p => recordedIds.Contains(p));
                SetScalarVariable(false, "tmp_on", count >= 3 ? "1" : "0");
                break;
            case "ranking":     // 生成当前排行并发送
                instance.OutputRanking(); break;
            case "recent":      // 生成最近一批上舰的名字列表并发送
                instance.OutputRecentNames(); break;
            default: throw new Exception("HoneyBeeRanking：不支持的参数");
        }
    }

    /// <summary> 生成最近一批上舰的名字列表并发送。 </summary>
    void OutputRecentNames()
    {
        RecentHexIds = GetListVariable(false, "HoneyBeeRecent").Values.Select(v => v.ToString()).ToList();
        SetListVariable(false, "HoneyBeeRecent", null);

        // /p <se.6>
        // ━━━━━━━━━━━━━━━━━
        // ♥ 蜂蜂小甜心 甜到你心中～ ♥
        // ♥ 歡迎兩位新艦長上艦～ ♥
        // ☆ Aaaaa Bbbbb ☆
        // ☆ 阿阿阿 ☆

        string cnt = "";
        if (RecentHexIds.Count > 1)
        {
            cnt = (isSimp ? "零一两三四五六七八" : "零一兩三四五六七八")[RecentHexIds.Count] + "位";
        }

        string output = $@"/{channel} <se.6>
{sepBold}
♥ 蜂蜂小甜心  ☆  甜到你心中 ♥
";
        if (isSimp) output += $"♥ 从今天起～成为我的小工蜂 ♥\n♥ 欢迎{cnt}新舰长上舰～ ♥";
        else output += $"♥ 从今天起～成為我的小工蜂 ♥\n♥ 歡迎{cnt}新艦長上艦～ ♥";
        output += $"\n☆ {string.Join(" ☆\n☆ ", RecentHexIds.Select(id => GetPlayerDesc(id)))} ☆";
        RealPlugin.Instance.InvokeNamedCallback("command", output);
    }

    /// <summary> 从已解析的当前玩家中，根据 ID 生成描述，如 [职业] 名字。 </summary>
    string GetPlayerDesc(string hexId, string bkupName = null)
    {
        if (currentPlayers.TryGetValue(hexId, out var vd))
        {
            var name = $"{vd.GetValue("name")}";
            //if (vd.GetValue("id").ToString() == PlayerHexId) // 演示用
            //    name = "Argument Exception";
            return $"[{vd.GetValue(isSimp ? "jobCN2" : "jobEN3")}] {name}";
        }
        else return bkupName ?? hexId; // 不应进入此分支
    }

    static string sepBold = "━━━━━━━━━━━━━━━━━";
    static string sepThin = "─────────────────";

    /// <summary> 生成当前排行并发送。 </summary>
    void OutputRanking()
    {
        var currentPlayerIds = new HashSet<string>(currentPlayers.Keys);
        Ranking = ParseRecordedPlayersFromTable()
            .Where(p => currentPlayerIds.Contains(p.HexId))
            .OrderByDescending(p => p.Times)
            .ThenBy(p => p.LastUpdated)
            .ToList();
        GenerateRanking();

        /* /p <se.6>
         ━━━━━━━━━━━━━━━━━
         ☆ 蜂蜂小甜心 ☆ 小姐的 大♡航♡海～
         ─────────────────
         　　5 次　　Aaaaa Bbbbb
         　　3 次　　Cccccccc Dddddddd
         　　3 次　　阿阿阿
         　　1 次　　Eeeeee
         ━━━━━━━━━━━━━━━━━
         */

        string output = $"/{channel} <se.6>\n\n{sepBold}\n☆ 蜂蜂小甜心 ☆  ♥  ☆ 大航海排行 ☆\n";
        if (Ranking.Count() == 0) return;
        output += string.Join("\n", Ranking.Select(p => p.ToRankingString(this))) + "\n" + sepBold;
        RealPlugin.Instance.InvokeNamedCallback("command", "/e \n♡ 清空排行：/e bee reset");
        RealPlugin.Instance.InvokeNamedCallback("command", output);
    }

    /// <summary> 从永久表格中解析所有已记录的玩家数据。 </summary>
    IEnumerable<Player> ParseRecordedPlayersFromTable()
        => GetTableVariable(true, "HoneyBeeRanking")?.Rows
            ?.Select(row => new Player(
                hexId: row.Values[0],
                name: row.Values[1],
                times: row.Values[2],
                lastUpdated: row.Values[3]))
            ?? Enumerable.Empty<Player>();

    /// <summary> 计算排名，考虑并列 </summary>
    void GenerateRanking()
    {
        int rank = 1;
        for (int i = 0; i < Ranking.Count; i++)
        {
            Ranking[i].Rank = (i >= 1 && Ranking[i].Times == Ranking[i - 1].Times) // 当前的次数和前一个相同
                ? Ranking[i - 1].Rank : rank;
            rank++;
        }
    }

    public class Player
    {
        public string HexId { get; set; }
        public string Name { get; set; }
        public int Times { get; set; }
        public double LastUpdated { get; set; }
        public int Rank { get; set; }

        public Player(object hexId, object name, object times, object lastUpdated)
        {
            HexId = hexId.ToString();
            Name = name.ToString();
            Times = int.Parse(times.ToString(), System.Globalization.CultureInfo.InvariantCulture);
            LastUpdated = double.Parse(lastUpdated.ToString(), System.Globalization.CultureInfo.InvariantCulture);
        }

        public string ToRankingString(HoneyBeeRanking instance)
        {
            string rank = Rank.ToString().ToXivBlackBoxChar(true);
            string times = Times.ToString();
            times = new string(' ', (3 - times.Length) * 2) + times; // 左侧补全空格对齐
            string player = instance.GetPlayerDesc(HexId, Name);
            return $"{rank}　{times} 次　　{player}";
        }
    }
}

