Action.ExecScriptExpression:
using System;
using System.Drawing;
using System.Linq;
using System.Threading;
using System.Windows.Forms;
using Triggernometry.Core;
using Triggernometry.UI.Forms;
using static Triggernometry.UI.Forms.GameConfigForm;

RealPlugin.Instance.RegisterNamedCallback(S7bEntry.Info.ConfigName, new Action<object, string>((_, __) => S7bEntry.Start()), null);

public static class S7bEntry
{
    public static ConfigInfo Info = new ConfigInfo("阿卡狄亚中量级 M5-8 宝宝椅", null, null/*"阿洛 MnFeN"*/, "${env:prefix}_cfg");
    static Color Blue = Color.FromArgb(0x22, 0x66, 0xff);
    public static void RunConfigForm()
    {
        try { _RunConfigForm(); }
        catch (Exception ex)
        {
            MessageBox.Show("配置界面运行时遇到问题：\n\n" + ex, Info.Name, MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }

    private static void _RunConfigForm()
    {
        GameConfigForm form = new GameConfigForm(Info);
        form.Shown += (sender, e) => RealPlugin.Instance.InvokeNamedCallback("command", "/e <se.9>");

        BijectDictionary<string, string> cbxItems;
        Option optionCtrl;
        Label label;
        string hint = "";
        // 在下面倒序添加各个选项组（组内的选项正序）

        OptionsTableLayoutPanel tableM8s = form.AddOptionGroup(" M8s 剑嚎 ");
        cbxItems = new BijectDictionary<string, string>(
            ("国", " [国服] 斜八方固定位置"),
            ("美", " [美服] 浮游炮安全区方向 TH 顺 D 逆")
        );
        optionCtrl = new OptionCbx("　钢铁浮游炮时的分散站位", "M8s_钢铁站位", cbxItems, "国");
        form.AddOption(optionCtrl, tableM8s);
        cbxItems = new BijectDictionary<string, string>(
            ("1", " [国服] 先撞绿色风球"),
            ("0", " [美服] 先撞黄色土立方体")
        );
        optionCtrl = new OptionCbx("　小怪阶段消除风土 debuff 顺序", "M8s_b先撞绿", cbxItems, "1");
        form.AddOption(optionCtrl, tableM8s);
        /*
        cbxItems = new BijectDictionary<string, string>(
            ("顺次", " 连线顺次经过四个平台"),
            ("半场", " 分左右半场处理接线风圈和直线分摊")
        );
        optionCtrl = new OptionCbx("　[未适配] 本体传线解法", "M8s_传线", cbxItems, "顺次");
        form.AddOption(optionCtrl, tableM8s);
        */
        OptionsTableLayoutPanel tableM7s = form.AddOptionGroup(" M7s 野蛮恨心 ");
        cbxItems = new BijectDictionary<string, string>(
            ("1", " [国服] 相对面向基准"),
            ("0", " [美服] 绝对方向基准")
        );
        optionCtrl = new OptionCbx("　八方分散的方位基准", "M7s_b面基", cbxItems, "1");
        form.AddOption(optionCtrl, tableM7s);

        OptionsTableLayoutPanel tableM6s = form.AddOptionGroup(" M6s 狂热糖潮 ");
        cbxItems = new BijectDictionary<string, string>(
            ("国", " [国服] 危险仙人掌为北，左至右 H1-人群-H2"),
            ("美", " [美服] 危险仙人掌为南，左至右 H1-人群-H2"),
            ("日", " [日服] 绝对方向基准")
        );
        optionCtrl = new OptionCbx("　沙坑+仙人掌阶段的方位基准", "M6s_沙坑基准", cbxItems, "1");
        form.AddOption(optionCtrl, tableM6s);
        hint = "第一次飞行时的圆弧内为危险区域；\n第二次飞行时的橙色多边形区域为危险区域。\n只要不在危险区域内，即可纠正至正确方向。";
        optionCtrl = new OptionChk("  强制飞行前自动纠正面向，防止飞进电网或熔岩", "M6s_AutoFly", true, hint);
        form.AddOption(optionCtrl, tableM6s);

        OptionsTableLayoutPanel tableM5s = form.AddOptionGroup(" M5s 热舞绿光 ");
        form.AddLabel("  ", tableM5s);

        #region 使用须知

        OptionsTableLayoutPanel tableInfo = form.AddOptionGroup(" 使用须知 ");

        form.AddLabel("· 使用前必须查看使用说明，见绝伊甸触发器分组下的「使用说明」触发器。", tableInfo)
            .ForeColor = Blue;

        //label = form.AddLabel("· 下方部分选项上悬停鼠标可以显示详细说明。", tableInfo);
        //label.ForeColor = Blue;

        #endregion 使用须知

        Application.OpenForms.OfType<GameConfigForm>().ToList().ForEach(f => f.Close());
        form.Run();
    }


    [STAThread]
    public static void Start()
    {
        try
        {
            Application.OpenForms.OfType<GameConfigForm>().ToList().ForEach(f => f.Close());
            Thread staThread = new Thread(new ThreadStart(RunConfigForm));
            staThread.SetApartmentState(ApartmentState.STA);
            staThread.Start();
            staThread.Join();
        }
        catch (Exception ex)
        {
            MessageBox.Show("用户配置表单运行错误：\n" + ex, Info.Name, MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }
}

