 private static void p43dh(string xy) {
  var pos = GetXY(xy);
  lock (p43dhDist) {
   var iter = 0;
   foreach (var player in Players) {
    if (player.job is "ST" or "MT") continue;
    var pn = player.name;
    var pl = BridgeFFXIV.GetNamedPartyMember(pn);
    var dist = Vector2.DistanceSquared(pos,
     new Vector2(float.Parse(pl.GetValue("x").ToString()),
      float.Parse(pl.GetValue("y").ToString())));
    if (p43dhCount == 0) p43dhDist.Add(new DHP43(pn, dist));
    else {
     p43dhDist[iter].dist = Math.Min(p43dhDist[iter].dist, dist);
     iter++;
    }
   }
   if (++p43dhCount != 3) return;
   p43dhDist.Sort((a, b) => a.dist.CompareTo(b.dist));
   p43dh_fq(p43dhDist[0].name, "地火");
   p43dh_fq(p43dhDist[1].name, "地火");
   p43dh_fq(p43dhDist[2].name, "地火");
  }
 }
 private static void p41dihuo() {
 // 初始点和圆心
 Vector2 startPoint = new Vector2(100, 118);
 Vector2 center = new Vector2(100, 100);
 
 // 自定义角度转弧度函数
 float ToRadians(float degrees) => (float)(degrees * Math.PI / 180.0);
 
 // 旋转函数
 Vector2 RotatePoint(Vector2 point, Vector2 center, float angleRadians)
 {
  Vector2 translatedPoint = point - center;
  Vector2 rotatedPoint = new Vector2(
   translatedPoint.X * (float)Math.Cos(angleRadians) - translatedPoint.Y * (float)Math.Sin(angleRadians),
   translatedPoint.X * (float)Math.Sin(angleRadians) + translatedPoint.Y * (float)Math.Cos(angleRadians)
  );
  return rotatedPoint + center;
 }
 
 // 绘制原始点
 plug.InvokeNamedCallback("PictoACT", $"Omen: er_general_1f\nt: 25\nPos: {startPoint.X}, {startPoint.Y}\nScale: 1,1\nColor: 1, 1, 1, 0.9");
 if (Uauto)
 {
  plug.InvokeNamedCallback("command", $"/e 原始点:({startPoint.X:F1}, {startPoint.Y:F1})");
 }
 
 // 顺时针旋转三次：30度, 30度, 30度
 float currentAngle = 0;
 for (int i = 0; i < 3; i++)
 {
  currentAngle += 30;
  Vector2 rotatedPoint = RotatePoint(startPoint, center, ToRadians(currentAngle));
  
  // 使用PictoACT绘制omen
  plug.InvokeNamedCallback("PictoACT", $"Omen: er_general_1f\nt: 25\nPos: {rotatedPoint.X}, {rotatedPoint.Y}\nScale: 1,1\nColor: 0.1, 1, 0.1, 0.9");
  
  if (Uauto)
  {
   plug.InvokeNamedCallback("command", $"/e 顺时针第{i+1}次旋转(累计{currentAngle}度) - 点:({rotatedPoint.X:F1}, {rotatedPoint.Y:F1})");
  }
 }
 
 // 逆时针旋转三次：30度, 30度, 30度
 currentAngle = 0;
 for (int i = 0; i < 3; i++)
 {
  currentAngle -= 30;
  Vector2 rotatedPoint = RotatePoint(startPoint, center, ToRadians(currentAngle));
  
  // 使用PictoACT绘制omen
  plug.InvokeNamedCallback("PictoACT", $"Omen: er_general_1f\nt: 25\nPos: {rotatedPoint.X}, {rotatedPoint.Y}\nScale: 1,1\nColor: 1, 0.1, 0.1, 0.9");
  
  if (Uauto)
  {
   plug.InvokeNamedCallback("command", $"/e 逆时针第{i+1}次旋转(累计{Math.Abs(currentAngle)}度) - 点:({rotatedPoint.X:F1}, {rotatedPoint.Y:F1})");
  }
 }
}

