 private static void p2zhuzi23() {
  if (Zhuzi2.X is 83.88f or 93.3f) Zhuzi2.X = 88;
  if (Zhuzi2.X is 106.7f or 116.12f) Zhuzi2.X = 112;
  if (Zhuzi2.Y is 83.88f or 93.3f) Zhuzi2.Y = 88;
  if (Zhuzi2.Y is 106.7f or 116.12f) Zhuzi2.Y = 112;
  Place($"2:{Zhuzi2.X},{Zhuzi2.Y};3:{200 - Zhuzi2.X},{200 - Zhuzi2.Y}");
  
  // 三点坐标
  Vector2 point3 = new Vector2(200 - Zhuzi2.X, 200 - Zhuzi2.Y);
  // 圆心
  Vector2 center = new Vector2(100, 100);
  
  // 自定义角度转弧度函数
  float ToRadians(float degrees) => (float)(degrees * Math.PI / 180.0);
  
  // 旋转函数
  Vector2 RotatePoint(Vector2 point, Vector2 center, float angleRadians)
  {
   Vector2 translatedPoint = point - center;
   Vector2 rotatedPoint = new Vector2(
    translatedPoint.X * (float)Math.Cos(angleRadians) - translatedPoint.Y * (float)Math.Sin(angleRadians),
    translatedPoint.X * (float)Math.Sin(angleRadians) + translatedPoint.Y * (float)Math.Cos(angleRadians)
   );
   return rotatedPoint + center;
  }
  
  // 顺时针旋转四次：45度, 30度, 30度, 30度
  Vector2[] clockwisePoints = new Vector2[4];
  float[] clockwiseAngles = { 45, 30, 30, 30 };
  float currentAngle = 0;
  
  for (int i = 0; i < 4; i++)
  {
   currentAngle += clockwiseAngles[i];
   Vector2 rotatedPoint1 = RotatePoint(point3, center, ToRadians(currentAngle));
   
   clockwisePoints[i] = rotatedPoint1;
   
   // 使用PictoACT绘制omen - 每次旋转只绘制一个点
   // 修改颜色从蓝色到绿色渐变
   float blue = 1.0f - (i * 0.25f); // 蓝色分量从1递减到0.25
   float green = 0.1f + (i * 0.25f); // 绿色分量从0.1递增到0.85
   plug.InvokeNamedCallback("PictoACT", $"Omen: er_general_1f\nt: 25\nPos: {rotatedPoint1.X}, {rotatedPoint1.Y}\nScale: 1,1\nColor: 0.1,{green:F1},{blue:F1}, 0.9");
   
   if (Uauto)
   {
    plug.InvokeNamedCallback("command", $"/e 顺时针第{i+1}次旋转(累计{currentAngle}度) - 点:({rotatedPoint1.X:F1}, {rotatedPoint1.Y:F1})");
   }
  }
  
  // 逆时针旋转四次：45度, 30度, 30度, 30度
  Vector2[] counterclockwisePoints = new Vector2[4];
  float[] counterclockwiseAngles = { -45, -30, -30, -30 };
  currentAngle = 0;
  
  for (int i = 0; i < 4; i++)
  {
   currentAngle += counterclockwiseAngles[i];
   Vector2 rotatedPoint1 = RotatePoint(point3, center, ToRadians(currentAngle));
   
   counterclockwisePoints[i] = rotatedPoint1;
   
   // 使用PictoACT绘制omen - 每次旋转只绘制一个点
   // 修改颜色从蓝色到绿色渐变
   float blue = 1.0f - (i * 0.25f); // 蓝色分量从1递减到0.25
   float green = 0.1f + (i * 0.25f); // 绿色分量从0.1递增到0.85
   plug.InvokeNamedCallback("PictoACT", $"Omen: er_general_1f\nt: 25\nPos: {rotatedPoint1.X}, {rotatedPoint1.Y}\nScale: 1,1\nColor: 0.1,{green:F1},{blue:F1}, 0.9");
   
   if (Uauto)
   {
    plug.InvokeNamedCallback("command", $"/e 逆时针第{i+1}次旋转(累计{currentAngle}度) - 点:({rotatedPoint1.X:F1}, {rotatedPoint1.Y:F1})");
   }
  }
 }

